/* kompila lead recovery · v2.1 · casca, papéis e telas
   Uma coisa grande por tela. Card de um número só. Lista de uma linha. A regra do cliente mora no Conector. */
(function(){
  const M=60000, H=3600000;
  const ls=(k,v)=>{try{if(v===undefined)return localStorage.getItem(k);localStorage.setItem(k,v)}catch(e){return null}};
  const DATA=window.K2_DATA;
  /* atalhos por URL: ?co=mrv  ?ver=g (gerente) ou ?ver=<id da pessoa> */
  (function(){const q=new URLSearchParams(location.search); if(q.get('co')&&DATA[q.get('co')])ls('k2_co',q.get('co')); const v=q.get('ver'); if(v==='g')ls('k2_papel','gerente'); else if(v){ls('k2_papel','vendedor');ls('k2_vend',v)} if(q.get('ajuda'))ls('k2_help',q.get('ajuda'))})();
  const coId=(DATA[ls('k2_co')]?ls('k2_co'):'p1led');
  const co=DATA[coId];
  const papel=ls('k2_papel')||'gerente';
  const gerente=co.pessoas.find(p=>p.papel==='gerente');
  const vendId=ls('k2_vend')||co.pessoas.find(p=>p.papel!=='gerente'&&p.papel!=='supervisora da IA').id;
  const me=papel==='gerente'?gerente:(co.pessoas.find(p=>p.id===vendId)||co.pessoas[1]);
  const q=new URLSearchParams(location.search);
  const per=q.get('p')||'hoje';

  /* ---------- helpers ---------- */
  const fmt=(ms)=>{ms=Math.max(0,ms);const m=Math.floor(ms/M); if(m<1)return Math.floor(ms/1000)+' s'; if(m<60)return m+' min'; const h=Math.floor(m/60); if(h<24)return h+' h '+String(m%60).padStart(2,'0'); const d=Math.floor(h/24); return d+' d '+(h%24)+' h'};
  const hhmm=(t)=>new Date(t).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});
  const dia=(t)=>new Date(t).toLocaleDateString('pt-BR',{weekday:'short',day:'2-digit',month:'2-digit'});
  const brl=(v)=>v==null?'a definir':co.moeda+' '+Math.round(v).toLocaleString('pt-BR');
  const brlk=(v)=>v>=1e6?co.moeda+' '+(v/1e6).toLocaleString('pt-BR',{maximumFractionDigits:2})+' mi':v>=1000?co.moeda+' '+Math.round(v/1000)+' mil':brl(v);
  const pct=(x,d)=>(x*100).toFixed(d||0).replace('.',',')+'%';
  const pessoa=(id)=>co.pessoas.find(p=>p.id===id);
  const nome=(id)=>(pessoa(id)||{nome:'IA'}).nome;
  const av=(id,s)=>{const p=pessoa(id); return p?`<span class="av${s?' s':''}" title="${p.nome}">${p.ini}</span>`:`<span class="av ia${s?' s':''}" title="IA">IA</span>`};
  const toast=(html)=>{let t=document.querySelector('.toast'); if(!t){t=document.createElement('div');t.className='toast';document.body.appendChild(t)} t.innerHTML=html; t.classList.add('on'); clearTimeout(t._h); t._h=setTimeout(()=>t.classList.remove('on'),3400)};
  const ESTADO={ia:'com a IA',lead:'esperando o lead',humano:'precisa de gente',agendado:'visita marcada',proposta:'proposta enviada',fechado:'fechado',perdido:'perdido',reabrindo:'reabrindo'};
  const est=(e)=>`<span class="est ${e}">${ESTADO[e]||e}</span>`;
  const conduz=(l)=>l.estado==='humano'?nome(l.pend?l.pend.para:l.dono):'IA';
  /* período: multiplica os números de hoje pra dar ordem de grandeza (mock) */
  const PER={hoje:{l:'Hoje',k:1},ontem:{l:'Ontem',k:1},semana:{l:'Semana',k:6},mes:{l:'Mês',k:co.mes.dia}};
  const K=(PER[per]||PER.hoje).k;
  const seg=(base)=>`<div class="seg">${Object.entries(PER).map(([k,v])=>`<a href="${base}?p=${k}" class="${per===k?'on':''}">${v.l}</a>`).join('')}</div>`;

  /* estado mutável */
  let saved=null; try{saved=JSON.parse(ls('k2_leads_'+coId)||'null')}catch(e){}
  if(saved){saved.forEach(s=>{const l=co.leads.find(x=>x.id===s.id); if(l){l.estado=s.estado; l.pend=s.pend; l.fase=s.fase||l.fase; if(s.fase_por){l.fase_por=s.fase_por;l.fase_t=s.fase_t} if(s.msgs)l.msgs=s.msgs;}})}
  const save=()=>ls('k2_leads_'+coId,JSON.stringify(co.leads.map(l=>({id:l.id,estado:l.estado,fase:l.fase,fase_por:l.fase_por,fase_t:l.fase_t,pend:l.pend||null,msgs:l.msgs}))));
  const pendencias=(all)=>co.leads.filter(l=>l.estado==='humano'&&l.pend&&(all||l.pend.para===me.id)).map(l=>({l,p:l.pend,espera:Date.now()-l.pend.desde,late:(Date.now()-l.pend.desde)>l.pend.sla_min*M})).sort((a,b)=>b.espera-a.espera);
  const meusLeads=()=>papel==='gerente'?co.leads:co.leads.filter(l=>l.dono===me.id);

  const IC={
    zap:'<path d="M13 2 3 14h9l-1 8 10-12h-9l1-8z"/>',
    gauge:'<path d="m12 14 4-4"/><path d="M3.34 19a10 10 0 1 1 17.32 0"/>',
    chat:'<path d="M7.9 20A9 9 0 1 0 4 16.1L2 22Z"/>',
    eye:'<path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7-10-7-10-7Z"/><circle cx="12" cy="12" r="3"/>',
    clock:'<circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/>',
    alert:'<path d="m21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3Z"/><path d="M12 9v4"/><path d="M12 17h.01"/>',
    bell:'<path d="M6 8a6 6 0 0 1 12 0c0 7 3 9 3 9H3s3-2 3-9"/><path d="M10.3 21a1.94 1.94 0 0 0 3.4 0"/>',
    search:'<circle cx="11" cy="11" r="8"/><path d="m21 21-4.3-4.3"/>',
    user:'<path d="M19 21v-2a4 4 0 0 0-4-4H9a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/>',
    users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/>',
    check:'<path d="M20 6 9 17l-5-5"/>',
    send:'<path d="m22 2-7 20-4-9-9-4Z"/><path d="M22 2 11 13"/>',
    flame:'<path d="M8.5 14.5A2.5 2.5 0 0 0 11 12c0-1.38-.5-2-1-3-1.072-2.143-.224-4.054 2-6 .5 2.5 2 4.9 4 6.5 2 1.6 3 3.5 3 5.5a7 7 0 1 1-14 0c0-1.153.433-2.294 1-3a2.5 2.5 0 0 0 2.5 2.5z"/>',
    shield:'<path d="M20 13c0 5-3.5 7.5-7.66 8.95a1 1 0 0 1-.67-.01C7.5 20.5 4 18 4 13V6a1 1 0 0 1 1-1c2 0 4.5-1.2 6.24-2.72a1.17 1.17 0 0 1 1.52 0C14.51 3.81 17 5 19 5a1 1 0 0 1 1 1z"/>',
    target:'<circle cx="12" cy="12" r="10"/><circle cx="12" cy="12" r="6"/><circle cx="12" cy="12" r="2"/>',
    moon:'<path d="M12 3a6 6 0 0 0 9 9 9 9 0 1 1-9-9Z"/>',
    refresh:'<path d="M21 12a9 9 0 0 0-9-9 9.75 9.75 0 0 0-6.74 2.74L3 8"/><path d="M3 3v5h5"/><path d="M3 12a9 9 0 0 0 9 9 9.75 9.75 0 0 0 6.74-2.74L21 16"/><path d="M16 16h5v5"/>',
    bot:'<rect x="3" y="11" width="18" height="10" rx="2"/><circle cx="12" cy="5" r="2"/><path d="M12 7v4"/><path d="M8 16h.01"/><path d="M16 16h.01"/>',
    download:'<path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><path d="m7 10 5 5 5-5"/><path d="M12 15V3"/>',
    x:'<path d="M18 6 6 18"/><path d="m6 6 12 12"/>',
    calendar:'<rect x="3" y="4" width="18" height="18" rx="2"/><path d="M16 2v4"/><path d="M8 2v4"/><path d="M3 10h18"/>',
    coins:'<path d="M12 2v20"/><path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"/>',
    inbox:'<path d="M22 12h-6l-2 3h-4l-2-3H2"/><path d="M5.45 5.11 2 12v6a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2v-6l-3.45-6.89A2 2 0 0 0 16.76 4H7.24a2 2 0 0 0-1.79 1.11z"/>',
    trend:'<path d="M22 7l-8.5 8.5-5-5L2 17"/><path d="M16 7h6v6"/>',
    arrow:'<path d="M5 12h14"/><path d="m12 5 7 7-7 7"/>',
    plug:'<path d="M12 22v-5"/><path d="M9 8V2"/><path d="M15 8V2"/><path d="M18 8v5a4 4 0 0 1-4 4h-4a4 4 0 0 1-4-4V8Z"/>',
    key:'<path d="m21 2-2 2m-7.61 7.61a5.5 5.5 0 1 1-7.778 7.778 5.5 5.5 0 0 1 7.777-7.777zm0 0L15.5 7.5m0 0 3 3L22 7l-3-3m-3.5 3.5L19 4"/>',
    hand:'<path d="M18 11V6a2 2 0 0 0-4 0v5"/><path d="M14 10V4a2 2 0 0 0-4 0v2"/><path d="M10 10.5V6a2 2 0 0 0-4 0v8"/><path d="M18 8a2 2 0 1 1 4 0v6a8 8 0 0 1-8 8h-2c-2.8 0-4.5-.86-5.99-2.34l-3.6-3.6a2 2 0 0 1 2.83-2.82L7 15"/>',
    list:'<path d="M8 6h13"/><path d="M8 12h13"/><path d="M8 18h13"/><path d="M3 6h.01"/><path d="M3 12h.01"/><path d="M3 18h.01"/>',
    sliders:'<path d="M4 21v-7"/><path d="M4 10V3"/><path d="M12 21v-9"/><path d="M12 8V3"/><path d="M20 21v-5"/><path d="M20 12V3"/><path d="M1 14h6"/><path d="M9 8h6"/><path d="M17 16h6"/>',
    image:'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="9" cy="9" r="2"/><path d="m21 15-3.09-3.09a2 2 0 0 0-2.83 0L6 21"/>',
    brain:'<path d="M12 5a3 3 0 1 0-5.997.125 4 4 0 0 0-2.526 5.77 4 4 0 0 0 .556 6.588A4 4 0 1 0 12 18Z"/><path d="M12 5a3 3 0 1 1 5.997.125 4 4 0 0 1 2.526 5.77 4 4 0 0 1-.556 6.588A4 4 0 1 1 12 18Z"/><path d="M15 13a4.5 4.5 0 0 1-3-4 4.5 4.5 0 0 1-3 4"/><path d="M17.599 6.5a3 3 0 0 0 .399-1.375"/><path d="M6.003 5.125A3 3 0 0 0 6.401 6.5"/><path d="M3.477 10.896a4 4 0 0 1 .585-.396"/><path d="M19.938 10.5a4 4 0 0 1 .585.396"/><path d="M6 18a4 4 0 0 1-1.967-.516"/><path d="M19.967 17.484A4 4 0 0 1 18 18"/>',
    dot:'<circle cx="12" cy="12" r="4" fill="currentColor" stroke="none"/>',
    kanban:'<path d="M6 5v11"/><path d="M12 5v6"/><path d="M18 5v14"/>',
    chevron:'<path d="m6 9 6 6 6-6"/>'
  };

  const icon=(n,s)=>`<svg class="i" width="${s||18}" height="${s||18}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${IC[n]||''}</svg>`;
  const spark=(arr,w,h,cls)=>{w=w||72;h=h||26;const mx=Math.max(...arr),mn=Math.min(...arr);const pts=arr.map((v,i)=>[(i/(arr.length-1))*w,h-((v-mn)/((mx-mn)||1))*(h-4)-2]);const d=pts.map((p,i)=>(i?'L':'M')+p[0].toFixed(1)+' '+p[1].toFixed(1)).join(' ');return `<svg class="spark ${cls||''}" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}"><path d="${d} L${w} ${h} L0 ${h}Z" class="a"/><path d="${d}" class="l"/><circle cx="${pts.at(-1)[0]}" cy="${pts.at(-1)[1]}" r="2.5" class="e"/></svg>`};
  /* card de um número: l rótulo, v valor, s linha de baixo, cls cor, o = {sp:[7 dias], help:'o que é', bad:true se subir é ruim} */
  const num=(l,v,s,cls,o)=>{o=o||{}; const dark=cls&&cls.includes('dark'); return `<div class="num ${dark?'dark':''}" ${o.help?`data-help="${o.help}"`:''}><span class="l">${l}</span>${o.sp?`<div class="sp"><span class="v ${cls||''}">${v}</span>${spark(o.sp,72,26,o.bad?'r':'')}</div>`:`<span class="v ${cls||''}">${v}</span>`}${s?`<span class="s">${s}</span>`:''}</div>`};

  /* ---------- navegação ---------- */
  const NAV_G=[['index.html','gauge','Agora','agora'],['pipeline.html','kanban','Pipeline','pipeline'],['fila.html','hand','Fila','fila'],['conversa.html','chat','Conversas','conversa'],['leads.html','list','Leads','leads'],['equipe.html','users','Equipe','equipe'],['resultado.html','coins','Resultado','resultado'],['conector.html','key','Conector','conector']];
  const NAV_V=[['index.html','gauge','Meu resultado','agora'],['pipeline.html','kanban','Meu pipeline','pipeline'],['fila.html','hand','Precisa de mim','fila'],['conversa.html','chat','Conversas','conversa'],['leads.html','list','Meus leads','leads']];

  function shell(o){
    const NAV=papel==='gerente'?NAV_G:NAV_V; const pend=pendencias(papel==='gerente');
    const item=(n)=>{const isCon=n[3]==='conector'; const label=isCon?`<span class="cl"><img src="${co.logo}" alt=""></span><span class="t">Conector ${co.nome.split(' ·')[0]}</span>`:`${icon(n[1])}<span class="t">${n[2]}</span>`;
      const badge=n[3]==='fila'&&pend.length?`<span class="n ${pend.some(p=>p.late)?'bad':''}">${pend.length}</span>`:''; return `<a href="${n[0]}" class="${o.active===n[3]?'active':''}">${label}${badge}</a>`};
    const rail=document.createElement('aside'); rail.className='k-rail';
    rail.innerHTML=`<div class="k-logo"><span class="sig"><i>[</i> kompila <i>]</i></span><small>lead recovery</small></div>
      <nav class="k-nav">${NAV.slice(0,5).map(item).join('')}</nav>
      ${papel==='gerente'?`<div class="k-sec">Gestão</div><nav class="k-nav">${NAV.slice(5,7).map(item).join('')}</nav><div class="k-sec">Inteligência</div><nav class="k-nav">${NAV.slice(7).map(item).join('')}</nav>`:''}
      <div class="foot"><div class="co-badge"><span class="cl"><img src="${co.logo}" alt="${co.nome}"></span><div><b>${co.nome}</b>${co.setor}</div></div></div>`;
    const top=document.createElement('header'); top.className='k-top';
    const navItem=NAV.find(n=>n[3]===o.active);
    document.body.classList.toggle('help',ls('k2_help')==='1');
    top.innerHTML=`<span class="crumb">${navItem?(o.active==='conector'?'Conector '+co.nome.split(' ·')[0]:navItem[2]):o.title}</span>
      <label class="sel">${icon('key',14)}<select id="k-co">${Object.values(DATA).map(c=>`<option value="${c.id}" ${c.id===coId?'selected':''}>${c.nome}</option>`).join('')}</select></label>
      ${co.exemplo?`<span class="ex">números de exemplo</span>`:''}
      <label class="search">${icon('search',15)}<input placeholder="Buscar lead, telefone, vendedor"></label>
      <span class="sp"></span><span class="clock" id="k-clock"></span>
      <span class="help ${ls('k2_help')==='1'?'on':''}" id="k-help" title="Liga um ? em cada bloco; passe o mouse pra ler o que ele é">${icon('eye',15)}Ajuda<span class="sw"></span></span>
      <span class="ib" title="Notificações">${icon('bell',16)}${pend.length?`<i>${pend.length}</i>`:''}</span>
      <label class="sel" title="Ver como">${av(me.id,true)}<select id="k-papel"><option value="g" ${papel==='gerente'?'selected':''}>${gerente.nome} · gerente</option>${co.pessoas.filter(p=>p.papel!=='gerente').map(p=>`<option value="${p.id}" ${papel==='vendedor'&&me.id===p.id?'selected':''}>${p.nome} · ${p.papel}</option>`).join('')}</select></label>`;
    document.body.prepend(top); document.body.prepend(rail);
    const tick=()=>{document.getElementById('k-clock').textContent=new Date().toLocaleDateString('pt-BR',{weekday:'short',day:'2-digit',month:'short'})+' · '+new Date().toLocaleTimeString('pt-BR')};tick();setInterval(tick,1000);
    document.getElementById('k-help').onclick=()=>{ls('k2_help',ls('k2_help')==='1'?'0':'1');document.body.classList.toggle('help');document.getElementById('k-help').classList.toggle('on')};
    document.getElementById('k-co').onchange=(e)=>{ls('k2_co',e.target.value);location.href=location.pathname};
    document.getElementById('k-papel').onchange=(e)=>{const v=e.target.value; if(v==='g'){ls('k2_papel','gerente')}else{ls('k2_papel','vendedor');ls('k2_vend',v)} location.href=location.pathname};
    window.K2_reset=()=>{localStorage.removeItem('k2_leads_'+coId);location.reload()};
  }
  const head=(t,right)=>`<div class="k-head"><h1>${t}</h1><div class="right">${right||''}</div></div>`;
  const fonte=()=>`<p class="fonte">${co.fonte}</p>`;

  /* pendência em uma linha, abre no clique */
  const pendRow=(pp,all)=>{const {l,p,espera,late}=pp; const aprova=p.tipo.startsWith('Proposta')||p.tipo.startsWith('Lead pediu')||p.tipo==='IA insegura';
    return `<div class="pend" id="p${l.id}"><div class="top" onclick="this.parentNode.classList.toggle('open')">
      <span class="t ${late?'r':'a'}">${fmt(espera)}</span>
      <span><b>${l.nome}</b> <span class="muted">· ${brl(l.valor)}</span><span class="sub">${p.tipo}${all?' · com '+nome(p.para)+(pessoa(p.para)&&!pessoa(p.para).online?' (offline)':''):''}</span></span>
      <span class="acts"><button class="btn ok sm" onclick="event.stopPropagation();K2.${aprova?'aprovar':'decidir'}(${l.id})">${aprova?(p.tipo.startsWith('Proposta')?'Aprovar':'Aprovar rascunho'):'Decidir'}</button><a class="btn sm" href="conversa.html?l=${l.id}" onclick="event.stopPropagation()">Abrir</a></span>
      <span class="muted">${icon('chevron',16)}</span></div>
      <div class="det">Regra do conector: <b>${p.regra}</b>. Prazo ${p.sla_min} min.<div class="sug"><b>O que a IA sugere</b>${p.sugestao}</div><div style="margin-top:8px"><button class="btn ghost sm" onclick="K2.devolver(${l.id})">Devolver pra IA</button></div></div></div>`};


  /* faixa: onde cada lead está no pipeline, quem conduz (IA ou pessoa), e quanto vale */
  const band=()=>{const leads=meusLeads(); const modo=q.get('b')||'fase'; const humano=leads.filter(l=>l.estado==='humano').length; const tot=leads.length||1;
    const tog=`<div class="seg"><a href="?b=fase${per!=='hoje'?'&p='+per:''}" class="${modo==='fase'?'on':''}">Por fase</a><a href="?b=espera${per!=='hoje'?'&p='+per:''}" class="${modo==='espera'?'on':''}">Por espera</a></div>`;
    if(modo==='espera'){const R=co.regra; const pend=pendencias(papel==='gerente'); const bks=[['até '+R.humano_min+' min',0,R.humano_min*M],[R.humano_min+' a 30 min',R.humano_min*M,30*M],['30 min a 1 h',30*M,60*M],['1 a 5 h',60*M,300*M],['5 a 24 h',300*M,24*H],['mais de 24 h',24*H,Infinity]];
      return `<div class="band" data-help="Quem está esperando uma pessoa, por quanto tempo. Verde é dentro do prazo do conector; vermelho estourou. As bolinhas pequenas são quem está segurando. Clique em Por fase pra ver o pipeline."><div class="bh"><h2>Quem está esperando gente, por tempo</h2><span class="c">${pend.length} leads parados · prazo ${R.humano_min} min</span><div class="r">${tog}</div></div>
        <div class="brow" style="grid-template-columns:repeat(6,1fr)">${bks.map((b,i)=>{const ls_=pend.filter(x=>x.espera>=b[1]&&x.espera<b[2]); const n=ls_.length; const quem=[...new Set(ls_.map(x=>x.p.para))];
          return `<a class="bk" href="fila.html"><span class="ring ${n?'':'zero'}" style="--p:${n/(pend.length||1)*100};--c:${i===0?'var(--green-2)':i<3?'#f2b53d':'var(--red)'}"><b>${n}</b></span><span class="lb">${b[0]}</span><span class="sub">${i===0?'no prazo':i<3?'passou':'estourado'}</span><span class="avs">${quem.map(id=>av(id,true)).join('')}</span></a>`}).join('')}</div></div>`}
    const cols=[...co.pipeline,'Perdido'];
    return `<div class="band" data-help="Onde cada lead está no pipeline do cliente (as fases vêm do Conector). O número é quantos leads; embaixo, quanto valem; as bolinhas pequenas são quem conduz: IA ou a pessoa. Arco vermelho é fase com lead esperando gente. Clique em Por espera pra ver o relógio."><div class="bh"><h2>Onde cada lead está</h2><span class="c">${leads.length} leads · ${humano} esperando gente</span><div class="r">${tog}<a class="btn sm" href="pipeline.html">Pipeline</a></div></div>
      <div class="brow" style="grid-template-columns:repeat(${cols.length},1fr)">${cols.map(c=>{const ls_=leads.filter(l=>l.fase===c); const n=ls_.length; const hum=ls_.filter(l=>l.estado==='humano').length; const sum=ls_.reduce((s,l)=>s+(l.valor||0),0);
        const quem=[...new Set(ls_.map(l=>l.estado==='humano'?(l.pend?l.pend.para:l.dono):'ia'))];
        return `<a class="bk ${c==='Perdido'?'lost':''}" href="pipeline.html"><span class="ring ${n?'':'zero'}" style="--p:${n/tot*100};--c:${hum?'var(--red)':c==='Fechado'?'var(--carbon)':'var(--green-2)'}"><b>${n}</b></span><span class="lb">${c}</span><span class="sub">${sum?brlk(sum):'·'}</span><span class="avs">${quem.map(id=>id==='ia'?av(null,true):av(id,true)).join('')}</span></a>`}).join('')}</div></div>`};

  /* dica por nível (ideia da Kommo: iniciante / gerente no mesmo campo) */
  const DICAS={
    'Responder lead novo':['A IA responde na hora, mesmo de madrugada.','Meta: 15 s. Toda mensagem é assinada como assistente; nunca finge ser pessoa.'],
    'Cotar faixa de preço':['A IA pega o preço na tabela da empresa, não inventa.','Chama o motor cotar (Copiloto). Se o motor falhar, ela diz que o vendedor confirma e chama gente.'],
    'Dar desconto':['A IA nunca dá desconto sozinha.','Até a alçada do vendedor, ele aprova com um toque; acima, vai pro gerente. Desconto sobre projeto instalado.'],
    'Enviar proposta formal (PDF do Copiloto)':['A IA monta a proposta; o vendedor aprova.','Aprovar envia o PDF na conversa e move o lead pra Proposta. Sem aprovação em 60 min, vai pro gerente.'],
    'Lead pediu pra falar com uma pessoa':['Quando o lead pede gente, a IA para e chama.','Vai pro vendedor do lead; offline, avisa no celular; 2× o prazo, passa pro próximo online.'],
    'Confiança da IA abaixo de 70% em 2 mensagens seguidas':['Se a IA não tem certeza, ela não chuta.','Escala pra quem revisa o playbook; a resposta vira regra e a IA aprende pro próximo.'],
    'Pedir nota de 1 a 10 ao fechar a conversa':['Uma pergunta no fim: de 1 a 10, como foi?','Valida número, grava no lead. Nota até 6 avisa o gerente. Não vira ranking.']
  };
  const dica=(k)=>{const d=DICAS[k]; return d?`<span class="dica"><span title="${d[0]}">iniciante</span><span title="${d[1]}">gerente</span></span>`:''};
  const exportar=()=>{const o={cliente:co.nome,chave:'kmp_'+co.id,pipeline:co.pipeline,ia:co.ia,regra:co.regra,autonomia:co.autonomia,escalada:co.escalada,motores:co.motores.map(m=>({nome:m.nome,fonte:m.fonte,versao:m.versao})),templates:co.templates.map(t=>t.nome)}; const b=new Blob([JSON.stringify(o,null,2)],{type:'application/json'}); const a=document.createElement('a'); a.href=URL.createObjectURL(b); a.download='conector_'+co.id+'.json'; a.click(); toast('<b>Exportado.</b> conector_'+co.id+'.json: vira molde pro próximo cliente.')};

  const PAGES={};

  /* ===== AGORA (gerente) · MEU RESULTADO (vendedor) ===== */
  PAGES.agora=()=>{
    if(papel==='vendedor'){const p=me; const pend=pendencias(false); const meus=meusLeads();
      return head('Meu resultado',`<button class="btn ghost" onclick="K2_reset()">Zerar exemplo</button>`)+
      `<div class="nums">${num('Fechado no mês',brlk(p.valor),p.fechados+' venda'+(p.fechados!==1?'s':''),'dark g',{help:'O que você fechou no mês.'})}${num('Leads comigo',p.leads_mes,'no mês',null,{help:'Leads que a IA entregou pra você no mês.'})}${num('Visitas',p.visitas,'marcadas pela IA',null,{help:'Visitas que a IA marcou na sua agenda.'})}${num('Propostas',p.propostas,'aprovadas por mim',null,{help:'Propostas que a IA montou e você aprovou com um toque.'})}${num('Respondi em',p.sla_min+' min','prazo '+co.regra.humano_min+' min',p.sla_min<=co.regra.humano_min?'g':'a',{help:'Quanto tempo você leva, em média, pra resolver o que a IA pede. É o único relógio que conta contra você.'})}</div>
      ${band()}
      <div class="sec" data-help="O que a IA parou e está esperando você: aprovar proposta, responder o que ela não pode, assumir quem pediu pessoa."><div class="h"><h2>Precisa de mim</h2><span class="c">${pend.length}</span><div class="r"><a class="btn sm" href="fila.html">Ver tudo</a></div></div><div class="b">${pend.map(pp=>pendRow(pp,false)).join('')||'<p class="muted">Nada. A IA está cuidando dos seus leads.</p>'}</div></div>
      <div class="sec" data-help="O que a IA fez pelos seus leads sem você pedir: follow-up, lembrete, template, base reaberta. É o trabalho chato que sumiu da sua lista."><div class="h"><h2>A IA fez por mim</h2><span class="c">hoje</span></div><div class="b">${co.feed.filter(f=>{const l=co.leads.find(x=>x.id===f.lead);return l&&l.dono===me.id}).slice(0,5).map(f=>`<div class="row" style="grid-template-columns:44px 1fr"><span class="t muted">${hhmm(f.t)}</span><span>${f.tipo==='esc'?'<span class="tag r">parou</span> ':f.tipo==='lembrete'?'<span class="tag g">ninguém faria</span> ':''}${f.x}</span></div>`).join('')||'<p class="muted">Nada ainda hoje.</p>'}</div></div>
      <div class="sec tip-up" data-help="Seus leads, a fase no pipeline, o estado que a IA deu e o próximo passo que ela já agendou."><div class="h"><h2>Meus leads</h2><span class="c">${meus.length}</span></div><div class="b p0"><table><thead><tr><th>Lead</th><th>Fase</th><th>Estado</th><th class="n">Valor</th><th>Próximo passo</th></tr></thead><tbody>${meus.map(l=>`<tr class="link" onclick="location='conversa.html?l=${l.id}'"><td><b>${l.nome}</b><span class="sub">${l.interesse}</span></td><td>${l.fase}</td><td>${est(l.estado)}</td><td class="n mono">${brl(l.valor)}</td><td class="muted">${l.pend?'esperando você':l.proximo?l.proximo.acao+' · '+dia(l.proximo.quando):''}</td></tr>`).join('')}</tbody></table></div></div>`+fonte()}
    const h=co.hoje, m=co.mes, pend=pendencias(true), late=pend.filter(p=>p.late).length;
    const entr=per==='mes'?m.entraram:h.entraram*K, res=per==='mes'?Math.round(m.entraram*m.sem_humano):h.ia_resolveu*K, fech=per==='mes'?co.resultado.total:(per==='hoje'?20000:per==='ontem'?0:99000);
    const C=co.conv, R=co.resultado; const pond=R.pipe.reduce((s_,p)=>s_+p[3]*p[2],0);
    const hero=`<div class="hero" data-help="Conversão do mês: fechados sobre leads que entraram. Ao lado, a mesma conta separada por quem foi respondido em até ${co.regra.humano_min} min e quem esperou mais: é a prova de que velocidade vira venda. À direita, por pessoa."><div><span class="l">Conversão · setembro</span><div class="big">${pct(C.atual,1)}</div><span class="d"><span class="up">+${((C.atual-C.anterior)*100).toFixed(1).replace('.',',')} pts</span> vs ${pct(C.anterior,1)} no mês passado · ${m.fechou} fechados de ${m.entraram}</span><div style="margin-top:10px">${spark(C.hist,200,36)}</div></div>
      <div class="mid"><div class="st hi"><span class="l">gente respondeu em ${co.regra.humano_min} min</span><b>${pct(C.ate5,1)}</b><small>a regra funcionando</small></div><div class="st lo"><span class="l">respondeu depois</span><b>${pct(C.depois5,1)}</b><small>${(C.ate5/C.depois5).toFixed(1).replace('.',',')}× menos</small></div><div class="st"><span class="l">sem precisar de gente</span><b>${pct(m.sem_humano)}</b><small>a IA levou até o fim</small></div></div>
      <div class="pv"><span class="l">por pessoa</span>${co.pessoas.filter(p=>p.leads_mes>0&&p.papel!=='gerente').map(p=>`<div class="row">${av(p.id,true)}<div class="bar"><i style="width:${Math.min(100,p.fechados/p.leads_mes*100*8)}%"></i></div><span class="t">${pct(p.fechados/p.leads_mes,1)}</span><span class="t muted">${p.fechados}</span></div>`).join('')}</div></div>`;
    const resultado=`<div class="sec acc ${q.get('r')==='1'?'open':''}" data-help="Resultado do mês em dinheiro: o que fechou contra a meta, o pipeline ponderado pelo peso de cada fase (peso editável no Conector) e o que cada pessoa fechou. Fica fechado por padrão; abre no clique."><div class="h" onclick="this.parentNode.classList.toggle('open')"><h2>Resultado do mês</h2><span class="c">${brlk(R.total)} fechado · ${pct(R.total/R.meta)} da meta · ${brlk(pond)} ponderado no pipeline</span><div class="r"><span class="chev">${icon('chevron',18)}</span></div></div>
      <div class="b p0"><div class="res"><div><span class="l muted" style="font-size:12.5px">fechado</span><div class="big">${brl(R.total)}</div><span class="muted" style="font-size:13px">${R.n} vendas · ${brlk(R.total-R.hist.at(-2))} vs mês passado</span><div class="meta"><div class="bar"><i style="width:${Math.min(100,R.total/R.meta*100)}%"></i></div><div class="t"><span>meta ${brlk(R.meta)}</span><span>faltam ${brlk(Math.max(0,R.meta-R.total))}</span></div></div></div>
        <div><h5>pipeline · ${brlk(R.pipe.reduce((s_,p)=>s_+p[3],0))} bruto · ${brlk(pond)} ponderado</h5>${R.pipe.map(p=>`<div class="row" style="grid-template-columns:110px 1fr 80px 60px"><span>${p[0]}</span><div class="bar"><i style="width:${p[3]/R.pipe[1][3]*100}%"></i></div><span class="t">${brlk(p[3])}</span><span class="t muted">${p[1]} · ×${p[2]}</span></div>`).join('')}<p class="muted" style="font-size:12.5px;margin:8px 0 0">Se o mês seguir a média, fecha mais ${brlk(pond)}: ${R.total+pond>=R.meta?'bate a meta':'não bate a meta'}.</p></div>
        <div><h5>por pessoa</h5>${co.pessoas.filter(p=>p.papel!=='gerente'&&p.papel!=='supervisora da IA').map(p=>`<div class="row" style="grid-template-columns:22px 1fr 1fr 80px">${av(p.id,true)}<span>${p.nome}</span><div class="bar"><i style="width:${p.valor/(R.total||1)*100}%"></i></div><span class="t">${p.valor?brlk(p.valor):'0'}</span></div>`).join('')}<a class="btn sm" href="resultado.html" style="margin-top:10px">Resultado completo</a></div></div></div></div>`;
    return head('Agora',seg('index.html')+`<button class="btn ghost" onclick="K2_reset()">Zerar exemplo</button>`)+hero+
      `<div class="nums">${num('Leads',entr,per==='hoje'?h.fora_exp+' fora do expediente':'',null,{sp:m.hist_leads,help:'Quantos leads entraram no período, por qualquer canal. A linha é os últimos 7 dias.'})}${num('1ª resposta',h.resp_s+' s','a IA, 24 h','g',{sp:m.hist_resp_s,help:'Tempo entre a mensagem do lead e a primeira resposta da IA. Meta: 15 s, qualquer horário. No HubSpot da P1LED isso era horas ou nunca.'})}${num('Resolvido pela IA',pct(res/entr),res+' de '+entr,'g',{sp:m.hist_humano_pct.map(x=>1-x),help:'Fatia dos leads que a IA levou do começo ao fim sem chamar ninguém: qualificou, cotou, agendou, fechou ou perdeu com motivo.'})}${num('Precisa de gente',pend.length,late?late+' fora do prazo':'no prazo',late?'r':'a',{help:'Leads parados porque a IA chamou uma pessoa e ela ainda não agiu. É o único gargalo humano do sistema.'})}${num('Fechado',brlk(fech),'','dark g',{sp:R.hist,help:'Dinheiro fechado no período. A linha é os últimos 7 meses.'})}</div>
      ${band()}
      ${resultado}
      <div class="g21">
        <div class="sec" data-help="Leads travados esperando uma pessoa, do mais antigo pro mais novo. Cada linha: há quanto tempo espera, quem é, quanto vale, por que a IA parou e com quem está. Clique na linha pra ver a regra e o que a IA sugere; o botão verde resolve com um toque."><div class="h"><h2>Precisa de gente</h2><span class="c">${pend.length}</span><div class="r"><a class="btn sm" href="fila.html">Fila</a></div></div><div class="b">${pend.map(pp=>pendRow(pp,true)).join('')||'<p class="muted">Nada travado.</p>'}</div></div>
        <div><div class="sec tip-right" data-help="Diário da IA. Verde é o que ela fez que ninguém faria: follow-up no dia certo, lembrete de visita, template antes da janela fechar, perda com data de volta, base reaberta. Vermelho é quando parou e chamou gente. Tudo vira evento no banco."><div class="h"><h2>A IA hoje</h2><span class="c">${co.feed.filter(f=>f.tipo==='lembrete').length} coisas que ninguém faria</span></div><div class="b">${co.feed.slice(0,9).map(f=>`<div class="row" style="grid-template-columns:44px 1fr"><span class="t muted">${hhmm(f.t)}</span><span>${f.tipo==='esc'?'<span class="tag r">parou</span> ':f.tipo==='lembrete'?'<span class="tag g">ninguém faria</span> ':''}${f.x}</span></div>`).join('')}</div></div>
        <div class="sec tip-right" data-help="O relógio das pessoas: quanto tempo cada um leva pra resolver o que a IA pede (aprovar proposta, decidir desconto, responder o que a IA não pode) e quantos leads está segurando agora."><div class="h"><h2>Time</h2><span class="c">resolve o que a IA pede em</span></div><div class="b">${co.pessoas.map(p=>{const mine=pend.filter(x=>x.p.para===p.id);return `<div class="row" style="grid-template-columns:auto 1fr auto auto">${av(p.id,true)}<span><b>${p.nome}</b>${p.online?'':' <span class="tag r">offline</span>'}</span><span class="t ${p.sla_min<=co.regra.humano_min?'g':'a'}">${p.sla_min} min</span><span class="tag ${mine.some(x=>x.late)?'r':''}">${mine.length} na mão</span></div>`}).join('')}</div></div></div>
      </div>
      <div class="sec tip-up" data-help="Hora em que o lead chega, últimos 30 dias. Cinza é fora do expediente das pessoas; a IA atende igual, em segundos. É o argumento de venda contra o 'fora do expediente' do HubSpot."><div class="h"><h2>Hora em que o lead chega</h2><span class="c">últimos 30 dias · cinza é fora do expediente das pessoas; a IA atende igual</span></div><div class="b" style="padding:18px 20px 30px">${(()=>{const hs=coId==='mrv'?[2,1,1,1,1,2,3,5,8,11,13,14,13,12,12,13,14,13,12,11,9,7,5,3]:[1,1,0,1,1,2,4,7,10,12,13,14,12,11,11,10,9,7,5,4,3,2,2,1];const mx=Math.max(...hs);const off=(h)=>coId==='mrv'?(h<9||h>=20):(h<8||h>=18);const tot=hs.reduce((a,b)=>a+b,0);const fora=hs.filter((v,h)=>off(h)).reduce((a,b)=>a+b,0);return `<div style="display:flex;gap:4px;align-items:flex-end;height:110px">${hs.map((v,h)=>`<div style="flex:1;position:relative;height:${v/mx*100}%;min-height:2px;border-radius:3px 3px 0 0;background:${off(h)?'var(--line-2)':'var(--green)'}">${h%3===0?`<span style="position:absolute;bottom:-18px;left:0;right:0;text-align:center;font-size:11px;color:var(--mute)">${h}h</span>`:''}</div>`).join('')}</div><p class="muted" style="margin:26px 0 0;font-size:13px"><b style="color:var(--ink)">${pct(fora/tot)}</b> chegam fora de ${co.regra.expediente_humano}.</p>`})()}</div></div>`+fonte();
  };

  /* ===== PIPELINE (kanban com as fases do conector) ===== */
  PAGES.pipeline=()=>{const leads=meusLeads(); const f=q.get('f')||'todos';
    const lista=leads.filter(l=>f==='todos'||(f==='ia'&&l.estado!=='humano')||(f==='gente'&&l.estado==='humano'));
    const cols=[...co.pipeline,'Perdido'];
    const tot=leads.filter(l=>!['Perdido','Fechado'].includes(l.fase)).reduce((s,l)=>s+(l.valor||0),0);
    return head(papel==='gerente'?'Pipeline':'Meu pipeline',`<div class="seg"><a href="?f=todos" class="${f==='todos'?'on':''}">Todos</a><a href="?f=ia" class="${f==='ia'?'on':''}">Com a IA</a><a href="?f=gente" class="${f==='gente'?'on':''}">Com gente</a></div><span class="muted">${leads.length} leads · ${brlk(tot)} em aberto</span>${papel==='gerente'?`<a class="btn" href="conector.html?t=pipeline">Editar fases</a>`:''}`)+
      `<div class="kb" data-help="O pipeline do cliente: as fases vêm do Conector, não da kompila. A IA move o lead quando age (cotou, agendou); a pessoa também pode mover na conversa. Card com borda vermelha está esperando gente. O filtro separa o que a IA conduz do que está com pessoa.">${cols.map(c=>{const ls_=lista.filter(l=>l.fase===c); const sum=ls_.reduce((s,l)=>s+(l.valor||0),0);
        return `<div class="col ${c==='Perdido'?'lost':''}"><h3>${c}<span class="n">${ls_.length}</span></h3><div class="sum">${sum?brlk(sum):'·'}</div>${ls_.map(l=>`<a class="card ${l.estado==='humano'?'humano':''}" href="conversa.html?l=${l.id}"><b>${l.nome}</b><span class="i">${l.interesse}</span><span class="f">${av(l.estado==='humano'?(l.pend?l.pend.para:l.dono):null,true)}${l.estado==='humano'?nome(l.pend?l.pend.para:l.dono):'IA'}<span class="v">${l.valor?brlk(l.valor):''}</span></span></a>`).join('')}</div>`}).join('')}</div>`+fonte();
  };

  /* ===== FILA ===== */
  PAGES.fila=()=>{const all=papel==='gerente'; const pend=pendencias(all); const esperando=meusLeads().filter(l=>l.estado==='lead');
    return head(all?'Fila':'Precisa de mim',`<span class="tag ${pend.some(p=>p.late)?'r':'g'}">${pend.filter(p=>p.late).length} fora do prazo</span>`)+
      `<div class="sec" data-help="Tudo que está parado esperando uma pessoa, do mais antigo pro mais novo. Clique na linha pra ver a regra que fez a IA parar e o que ela sugere. Aprovar ou Decidir devolve o lead pra IA na hora."><div class="h"><h2>Esperando uma pessoa</h2><span class="c">${pend.length}</span></div><div class="b">${pend.map(pp=>pendRow(pp,all)).join('')||'<p class="muted">Nada parado.</p>'}</div></div>
      <div class="sec tip-up" data-help="Conversas em que a IA já respondeu e está esperando o lead voltar. Ninguém precisa fazer nada: o follow-up (dias 1, 3, 7, 14) já está agendado."><div class="h"><h2>Esperando o lead</h2><span class="c">${esperando.length} · follow-up já agendado</span></div><div class="b">${esperando.map(l=>`<div class="row link" style="grid-template-columns:1fr auto" onclick="location='conversa.html?l=${l.id}'"><span><b>${l.nome}</b><span class="sub">${(l.msgs.filter(m=>m.de==='ia').at(-1)||{}).x||''}</span></span><span class="t muted">${l.proximo?l.proximo.acao+' · '+dia(l.proximo.quando):''}</span></div>`).join('')||'<p class="muted">Nenhum.</p>'}</div></div>`+fonte();
  };

  /* ===== CONVERSAS ===== */
  PAGES.conversa=()=>{const leads=meusLeads(); const filtro=q.get('f')||'todas';
    const lista=leads.filter(l=>filtro==='todas'||(filtro==='gente'&&l.estado==='humano')||(filtro==='ia'&&l.estado!=='humano')).sort((a,b)=>(b.msgs.at(-1)||{t:0}).t-(a.msgs.at(-1)||{t:0}).t);
    const id=+q.get('l')||(leads.find(x=>x.id===1)||lista[0]||leads[0]).id; const l=co.leads.find(x=>x.id===id)||leads[0];
    const msg=(m)=>{if(m.de==='tool')return `<div class="msg tool"><span class="tag2">motor · ${m.name}</span><div class="kv">${Object.entries(m.out).map(([k,v])=>`<span class="k">${k}</span><span>${Array.isArray(v)?v.join(' · '):v}</span>`).join('')}</div></div>`;
      if(m.de==='sys')return `<div class="msg sys">${m.x}</div>`;
      const cls=m.de==='lead'?'lead':m.de==='ia'?'ia':m.de==='tpl'?'tpl':'hum'; const tag=m.de==='ia'?co.ia.assinatura:m.de==='tpl'?'template da Meta':m.de==='hum'?nome(m.por):'';
      return `<div class="msg ${cls}">${tag?`<span class="tag2">${tag}</span>`:''}${m.toque?'<span class="toque">respondeu com um toque</span>':''}${m.x}${m.botoes?`<div class="bts">${m.botoes.map(b=>`<span>${b}</span>`).join('')}</div>`:''}<span class="t">${hhmm(m.t)}</span></div>`};
    return head('Conversas')+
    `<div class="chat-wrap">
      <div class="chat-list" data-help="Todas as conversas, com quem está conduzindo cada uma. Com a IA: ela responde sozinha. Com gente: parou por regra e espera alguém."><div class="tabs">${[['todas','Todas'],['ia','Com a IA'],['gente','Com gente']].map(t=>`<a href="?f=${t[0]}&l=${l.id}" class="${filtro===t[0]?'on':''}">${t[1]}</a>`).join('')}</div>
        ${lista.map(x=>`<a class="it ${x.id===l.id?'on':''}" href="?f=${filtro}&l=${x.id}"><b>${x.nome}${est(x.estado)}</b><span>${(x.msgs.at(-1)||{}).x||''}</span></a>`).join('')}</div>
      <div class="chat" data-help="O WhatsApp do lead dentro do sistema. Verde é a IA; preto é pessoa; tracejado é o motor (o cálculo que a IA chamou, com entrada e saída); azul é template da Meta. Escrever aqui assume a conversa; Devolver pra IA solta."><div class="hd">${av(l.estado==='humano'?(l.pend?l.pend.para:l.dono):null)}<div><b>${l.nome}</b><span class="sub">${l.fase} · ${l.interesse} · ${brl(l.valor)}</span></div><div class="r">${est(l.estado)}</div></div>
        <div class="body">${l.msgs.map(msg).join('')}</div>
        <div class="foot">${l.estado==='humano'?`<div class="mode">${icon('hand',14)}A IA parou e espera <b>${conduz(l)}</b>.</div>${l.pend?`<div class="sug"><span onclick="K2.usarRascunho(this)">${l.pend.sugestao.replace(/^.*?Rascunho pronto: /,'').replace(/^.*?Sugestão: /,'')}</span></div>`:''}`:`<div class="mode">${icon('bot',14)}A IA está conduzindo. Escrever assume a conversa.</div>`}
          <div class="in"><input id="k-in" placeholder="${l.estado==='humano'?'Responder pra '+l.nome.split(' ')[0]:'Responder como '+me.nome}"><button class="btn pri" onclick="K2.enviar(${l.id})">Enviar</button>${l.estado==='humano'?`<button class="btn" onclick="K2.devolver(${l.id})">Devolver pra IA</button>`:''}</div></div></div>
      <div class="side">
        <div class="sec" data-help="O que a IA já entendeu deste lead, o que falta, o próximo passo que ela planejou e a confiança dela. Abaixo de 70% em 2 mensagens, ela para e chama gente."><div class="h"><h2>O que a IA apurou</h2><div class="r"><span class="tag ${l.ia.temperatura==='quente'?'r':l.ia.temperatura==='morna'?'a':''}">${l.ia.temperatura}</span></div></div><div class="b" style="padding:14px 20px"><dl>${l.ia.apurado.map(a=>`<dt>${a[0]}</dt><dd>${a[1]}</dd>`).join('')}</dl>${l.ia.falta.length?`<div class="falta"><span>Falta:</span> ${l.ia.falta.join(', ')}</div>`:''}<div class="next"><span>Próximo passo</span>${l.ia.proximo}</div><div style="display:flex;align-items:center;gap:8px;margin-top:10px;font-size:12px;color:var(--mute)">confiança<div class="bar" style="flex:1"><i class="${l.conf<0.7?'r':l.conf<0.85?'a':''}" style="width:${l.conf*100}%"></i></div>${Math.round(l.conf*100)}%</div></div></div>
        ${l.pend?`<div class="sec"><div class="h"><h2>Por que parou</h2></div><div class="b" style="padding:14px 20px;font-size:13px"><b>${l.pend.tipo}</b><span class="sub muted" style="display:block;margin-top:2px">${l.pend.regra}</span><p style="margin:8px 0 0;color:var(--ink-2)">${l.pend.sugestao}</p></div></div>`:''}
        <div class="sec tip-up" data-help="A fase é da IA: ela move quando age (cotou, agendou, mandou proposta). A pessoa só corrige quando a IA errou, e a correção vira evento e ensina o playbook."><div class="h"><h2>Fase</h2></div><div class="b" style="padding:12px 20px"><div style="font-size:13.5px"><b>${l.fase}</b><span class="sub" style="display:block;color:var(--mute);font-size:12.5px;margin-top:2px">${l.fase_por==='IA'?'a IA moveu · '+dia(l.fase_t)+' '+hhmm(l.fase_t):l.fase_por?l.fase_por+' corrigiu · '+dia(l.fase_t)+' '+hhmm(l.fase_t):'a IA moveu'}</span></div><details style="margin-top:10px"><summary style="font-size:12.5px;color:var(--mute);cursor:pointer">A IA errou? Corrigir</summary><div style="display:flex;flex-direction:column;gap:6px;margin-top:8px"><select onchange="K2.fase(${l.id},this.value)" style="height:34px;padding:0 10px">${[...co.pipeline,'Perdido'].map(f=>`<option ${f===l.fase?'selected':''}>${f}</option>`).join('')}</select><button class="btn ghost sm" onclick="K2.marcar(${l.id},'perdido')">Perdido, com motivo</button></div></details></div></div>
        ${l.proximo?`<div class="sec tip-up" data-help="O que a IA já deixou agendado pra este lead sem ninguém pedir: follow-up, lembrete de visita, template antes da janela fechar, volta da base esquecida."><div class="h"><h2>A IA vai fazer</h2></div><div class="b" style="padding:12px 20px;font-size:13.5px"><b>${l.proximo.acao}</b><span style="display:block;color:var(--mute);font-size:12.5px;margin-top:2px">${dia(l.proximo.quando)} ${hhmm(l.proximo.quando)} · sem ninguém lembrar</span></div></div>`:''}
      </div></div>`;
  };

  /* ===== LEADS ===== */
  PAGES.leads=()=>{const leads=meusLeads(); const f=q.get('e'); const lista=f?leads.filter(l=>l.estado===f):leads;
    return head(papel==='gerente'?'Leads':'Meus leads',`<div class="seg"><a href="leads.html" class="${!f?'on':''}">Todos</a><a href="?e=humano" class="${f==='humano'?'on':''}">Precisa de gente</a><a href="?e=ia" class="${f==='ia'?'on':''}">Com a IA</a><a href="?e=perdido" class="${f==='perdido'?'on':''}">Perdidos</a></div>`)+
    `<div class="sec"><div class="b p0"><table><thead><tr><th>Lead</th><th>Origem</th><th>Fase</th><th>Estado</th><th>Quem conduz</th><th class="n">Valor</th><th>Próximo passo</th></tr></thead><tbody>
      ${lista.map(l=>`<tr class="link" onclick="location='conversa.html?l=${l.id}'"><td><b>${l.nome}</b><span class="sub">${l.interesse} · ${l.cidade}</span></td><td class="muted">${l.origem}</td><td>${l.fase}</td><td>${est(l.estado)}</td><td>${conduz(l)}</td><td class="n mono">${brl(l.valor)}</td><td class="muted">${l.pend?'esperando '+nome(l.pend.para):l.proximo?l.proximo.acao+' · '+dia(l.proximo.quando):l.perda?(l.perda.volta?'reabre '+dia(l.perda.volta):'arquivado'):''}</td></tr>`).join('')}</tbody></table></div></div>`+fonte();
  };

  /* ===== EQUIPE ===== */
  PAGES.equipe=()=>{const pend=pendencias(true); const vs=co.pessoas; const cham=vs.reduce((s,p)=>s+p.pend_mes,0); const tme=Math.round(vs.reduce((s,p)=>s+p.sla_min*p.pend_mes,0)/cham);
    return head('Equipe',`<a class="btn" href="conector.html?t=escalada">Quando a IA chama gente</a>`)+
    `<div class="nums">${num('A IA chamou gente',cham,'vezes no mês')}${num('Time resolve em',tme+' min','prazo '+co.regra.humano_min+' min',tme<=co.regra.humano_min?'g':'a')}${num('Visitas',vs.reduce((s,p)=>s+p.visitas,0),'no mês')}${num('Propostas',vs.reduce((s,p)=>s+p.propostas,0),'aprovadas')}${num('Fechado',brlk(co.resultado.total),co.resultado.n+' vendas','dark g')}</div>
    <div class="sec" data-help="Uma linha por pessoa: leads que a IA entregou, quantas vezes a IA chamou, em quanto tempo resolveu, quantos está segurando agora, visitas, propostas e fechado. O relógio aqui é das pessoas, não da IA."><div class="b p0"><table><thead><tr><th>Pessoa</th><th class="n">Leads</th><th class="n">A IA chamou</th><th class="n">Resolveu em</th><th class="n">Na mão agora</th><th class="n">Visitas</th><th class="n">Propostas</th><th class="n">Fechado</th></tr></thead><tbody>
      ${vs.map(p=>{const mine=pend.filter(x=>x.p.para===p.id);return `<tr><td><div style="display:flex;gap:10px;align-items:center">${av(p.id)}<div><b>${p.nome}</b>${p.online?'':' <span class="tag r">offline</span>'}<span class="sub">${p.papel}</span></div></div></td><td class="n mono">${p.leads_mes||'·'}</td><td class="n mono">${p.pend_mes}</td><td class="n mono" style="color:${p.sla_min<=co.regra.humano_min?'var(--green)':p.sla_min<=co.regra.humano_min*2?'var(--amber)':'var(--red)'};font-weight:600">${p.sla_min} min</td><td class="n mono" style="${mine.some(x=>x.late)?'color:var(--red);font-weight:600':''}">${mine.length}</td><td class="n mono">${p.visitas||'·'}</td><td class="n mono">${p.propostas||'·'}</td><td class="n mono">${p.valor?brlk(p.valor):'·'}</td></tr>`}).join('')}</tbody></table></div></div>
    <div class="sec tip-up" data-help="Por que a IA parou e chamou alguém, no mês, por regra do Conector. Se um motivo cresce, é regra pra revisar: ou a IA passa a fazer sozinha, ou muda quem recebe."><div class="h"><h2>Por que a IA chamou gente</h2><span class="c">no mês</span><div class="r"><a class="btn sm" href="conector.html?t=escalada">Editar regras</a></div></div><div class="b">${(()=>{const ws=coId==='mrv'?[0.34,0.22,0.18,0.12,0.08,0.06]:[0.31,0.24,0.17,0.12,0.09,0.05,0.02];return co.escalada.map((e,i)=>`<div class="row" style="grid-template-columns:1fr 160px 50px"><span>${e.regra}<span class="sub">vai pra ${e.para}</span></span><div class="bar"><i style="width:${(ws[i]||0.02)*250}%"></i></div><span class="t">${Math.round(cham*(ws[i]||0.02))}</span></div>`).join('')})()}</div></div>`+fonte();
  };

  /* ===== RESULTADO ===== */
  PAGES.resultado=()=>{const R=co.resultado, m=co.mes; const pond=R.pipe.reduce((s,p)=>s+p[3]*p[2],0); const iaCost=m.entraram*co.ia.custo_atend+m.reabriu*0.05; const humCost=co.pessoas.reduce((s,p)=>s+p.pend_mes,0)*14;
    return head('Resultado',`<span class="muted">setembro · dia ${m.dia} de ${m.dias}</span><button class="btn">Exportar</button>`)+
    `<div class="nums">${num('Fechado',brlk(R.total),R.n+' vendas · meta '+brlk(R.meta),'dark g')}${num('Da meta',pct(R.total/R.meta),'faltam '+brlk(Math.max(0,R.meta-R.total)),R.total/R.meta>=0.8?'g':'a')}${num('Pipeline ponderado',brlk(pond),brlk(R.pipe.reduce((s,p)=>s+p[3],0))+' bruto')}${num('Custo da IA',brl(iaCost),(m.entraram+m.reabriu)+' atendimentos','g')}${num('Custo das pessoas',brl(humCost),co.pessoas.reduce((s,p)=>s+p.pend_mes,0)+' chamadas · estimativa')}</div>
    <div class="sec" data-help="Funil do mês pela IA: do que entrou ao que fechou. A caixa vermelha é quanto ela precisou de gente."><div class="h"><h2>O que a IA fez no mês</h2><span class="c">${pct(m.sem_humano)} dos leads sem precisar de gente</span></div><div class="funil">${[['Entraram',m.entraram],['Qualificou',m.qualificou],[coId==='mrv'?'Simulou':'Cotou',m.cotou],['Visita',m.agendou],['Proposta',m.proposta],['Fechou',m.fechou],['Chamou gente',Math.round(m.entraram*(1-m.sem_humano)),'r']].map(x=>`<div class="${x[2]||''}"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}</div></div>
    <div class="g2">
      <div class="sec"><div class="h"><h2>${R.n>R.fechados.length?'Últimos fechados':'Fechados'}</h2></div><div class="b">${R.fechados.map(f=>`<div class="row" style="grid-template-columns:1fr auto"><span><b>${f.o}</b><span class="sub">${f.p} · ${f.q} · IA: ${f.ia}</span></span><span class="t">${brl(f.v)}</span></div>`).join('')}</div></div>
      <div class="sec tip-up" data-help="Perdas só com motivo dito pelo lead. Lead que sumiu não é perdido: fica no ciclo de reabertura da base esquecida."><div class="h"><h2>Perdas</h2><span class="c">${m.perdeu} · só com motivo dito pelo lead</span></div><div class="b">${co.perdas.motivos.map(p=>`<div class="row" style="grid-template-columns:1fr 40px 110px"><span>${p[0]}</span><span class="t">${p[1]}</span><span class="t muted">${p[2]}</span></div>`).join('')}<div class="row" style="grid-template-columns:1fr"><span class="muted">Base reaberta: ${m.reabriu} leads, ${m.reabriu_resp} responderam (${pct(m.reabriu_resp/m.reabriu)}), custo ${brl(m.reabriu*0.05)}.</span></div></div></div>
    </div>`+fonte();
  };

  /* ===== CONECTOR ===== */
  PAGES.conector=()=>{const t=q.get('t')||'pipeline';
    const tabs=[['pipeline','Pipeline'],['autonomia','O que a IA faz'],['escalada','Quando chama gente'],['motores','Motores'],['templates','Templates'],['tom','Tom e horário'],['api','Chave e API']];
    let body='';
    if(t==='pipeline')body=`<div class="sec" data-help="As fases do pipeline deste cliente. É daqui que o kanban e as bolinhas do Agora saem. Cada fase tem quem move pra ela, quando, e o peso no pipeline ponderado."><div class="h"><h2>Fases do pipeline</h2><span class="c">a IA move o lead entre elas; a pessoa também pode</span><div class="r"><button class="btn sm">Adicionar fase</button><button class="btn pri sm">Salvar</button></div></div><div class="b" style="padding:18px 20px"><div class="fases">${co.pipeline.map((f,i)=>`<span>${f}</span>${i<co.pipeline.length-1?'<i>→</i>':''}`).join('')}<i>·</i><span class="muted">Perdido</span></div>
      <table style="margin-top:18px"><thead><tr><th>Fase</th><th>Quem move pra cá</th><th>Quando</th><th class="n">Peso no pipeline</th></tr></thead><tbody>${(coId==='mrv'?[['Novo','IA','lead entrou',0.03],['Simulado','IA','motor simular_mcmv respondeu',0.1],['Visita marcada','IA','agenda gravou',0.35],['Documentos','corretor','link de documentos enviado',0.5],['Análise Caixa','corretor','documentos recebidos',0.6],['Fechado','corretor','contrato assinado',1]]:[['Novo','IA','lead entrou',0.05],['Qualificado','IA','tem espaço, medida e distância',0.1],['Cotado','IA','motor cotar respondeu',0.15],['Visita','IA','agenda gravou',0.4],['Proposta','vendedor aprova','PDF do Copiloto enviado',0.6],['Fechado','vendedor','aceite e ficha cadastral',1]]).map(r=>`<tr><td><b>${r[0]}</b></td><td>${r[1]}</td><td class="muted">${r[2]}</td><td class="n mono">×${r[3]}</td></tr>`).join('')}</tbody></table></div></div>`;
    if(t==='autonomia')body=`<div class="sec" data-help="A regra central do Conector: cada ação da IA em três níveis. Sozinha: faz e registra. Pede aprovação: monta e espera um toque de quem está indicado. Nunca: encaminha pra pessoa."><div class="h"><h2>O que a IA faz sozinha, o que pede, o que nunca faz</h2><div class="r"><button class="btn pri sm">Salvar</button></div></div><div class="b">${co.autonomia.map(a=>`<div class="aut"><span><b>${a.acao}</b>${a.opcional?'<span class="opc">opcional</span>':''}${dica(a.acao)}</span><select class="lvl ${a.nivel}" onchange="this.className='lvl '+this.value"><option value="sozinha" ${a.nivel==='sozinha'?'selected':''}>Sozinha</option><option value="aprovacao" ${a.nivel==='aprovacao'?'selected':''}>Pede aprovação</option><option value="nunca" ${a.nivel==='nunca'?'selected':''}>Nunca</option></select><span class="como">${a.quem?`<b>${a.quem}</b> · `:''}${a.como}</span></div>`).join('')}</div></div>`;
    if(t==='escalada')body=`<div class="sec" data-help="Quando a IA para e chama gente: a regra, pra quem vai e o prazo da pessoa agir. Estourou, o gerente vê na Fila."><div class="h"><h2>Quando a IA para e chama uma pessoa</h2><div class="r"><button class="btn pri sm">Salvar</button></div></div><div class="b p0"><table><thead><tr><th>Regra</th><th>Vai pra</th><th class="n">Prazo da pessoa</th><th>Se estourar</th></tr></thead><tbody>${co.escalada.map(e=>`<tr><td><b>${e.regra}</b>${dica(e.regra)}</td><td>${e.para}</td><td class="n mono">${e.sla_min} min</td><td class="muted">${e.depois||''}</td></tr>`).join('')}</tbody></table></div></div>
      <div class="sec" data-help="A régua de tempo do cliente, escrita como frase. É o que na Kommo é um evento no log desligado; aqui é o que acontece, na ordem. Editável: os minutos e as horas são do Conector; a linha de 24 h é fixa da kompila."><div class="h"><h2>O tempo, escrito</h2><span class="c">o que acontece com um lead que ninguém pega</span></div><div class="tempo"><b>0 s</b><span>lead manda mensagem; a IA responde em até 15 s, qualquer horário.</span><b>${co.regra.humano_min} min</b><span>se a IA chamou uma pessoa e ela não agiu, avisa no celular.</span><b class="r">${co.regra.humano_min*2} min</b><span>passa pro próximo online; ninguém online, vai pro ${gerente.nome}.</span><b>23 h</b><span>conversa parada perto de fechar a janela da Meta: a IA manda o template de utilidade (R$ 0,05) e mantém o lead vivo.</span><b class="r">24 h</b><span>regra fixa da kompila: lead nunca morre por falta de gente. Volta pra fila com o relógio zerado e a IA retoma o follow-up nos dias ${co.regra.toques.join(', ')}.</span></div></div>`;
    if(t==='motores')body=`<div class="mot" data-help="Os motores: o LLM nunca calcula, ele chama um destes. Cada um tem fonte, versão, dono e um teste que roda aqui.">${co.motores.map(mo=>`<div class="m"><h4>${mo.nome}<span class="tag ${mo.erros?'a':'g'}">${mo.chamadas} chamadas · ${mo.erros} erro${mo.erros!==1?'s':''}</span></h4><p>${mo.desc}</p><div class="meta">${mo.fonte} · v${mo.versao} · ${mo.dono}</div><pre>${JSON.stringify(mo.teste.inp)}\n→ ${JSON.stringify(mo.teste.out).replace(/","/g,'", "')}</pre><div style="margin-top:8px"><button class="btn sm" onclick="K2.testar('${mo.nome}')">Testar</button></div></div>`).join('')}</div>`;
    if(t==='templates')body=`<div class="sec" data-help="Mensagens homologadas pela Meta pra fora da janela de 24 h. Dentro da janela a IA escreve livre; fora, só passa o que está aqui."><div class="h"><h2>Templates da Meta</h2><span class="c">fora da janela de 24 h só passa o que a Meta aprovou</span><div class="r"><button class="btn sm">Novo</button></div></div><div class="b p0"><table><thead><tr><th>Nome</th><th>Categoria</th><th>Status</th><th class="n">Usos</th><th class="n">Custo</th><th>Texto</th></tr></thead><tbody>${co.templates.map(tp=>`<tr><td class="mono">${tp.nome}</td><td>${tp.cat}</td><td><span class="tag ${tp.status==='aprovado'?'g':'a'}">${tp.status}</span></td><td class="n mono">${tp.usos}</td><td class="n mono">R$ ${tp.custo.toFixed(2).replace('.',',')}</td><td class="muted">${tp.texto}${tp.nota?`<span class="sub" style="color:var(--green)">${tp.nota}</span>`:''}</td></tr>`).join('')}</tbody></table></div></div>`;
    if(t==='tom')body=`<div class="sec"><div class="h"><h2>Tom e horário</h2><div class="r"><button class="btn pri sm">Salvar</button></div></div><div class="b" style="padding:18px 20px"><dl style="display:grid;grid-template-columns:180px 1fr;gap:12px 16px;margin:0;font-size:13.5px"><dt class="muted">Nome da IA</dt><dd style="margin:0"><input value="${co.ia.nome}" style="width:100%;height:36px;padding:0 12px"></dd><dt class="muted">Tom</dt><dd style="margin:0"><textarea style="width:100%;height:64px;padding:8px 12px">${co.ia.tom}</textarea></dd><dt class="muted">Modelo</dt><dd style="margin:0">${co.ia.frente} na frente · ${co.ia.retaguarda} na retaguarda</dd><dt class="muted">A IA atende</dt><dd style="margin:0"><b>${co.regra.ia_horario}</b></dd><dt class="muted">As pessoas atendem</dt><dd style="margin:0"><input value="${co.regra.expediente_humano}" style="width:100%;height:36px;padding:0 12px"></dd><dt class="muted">Pessoa responde em</dt><dd style="margin:0"><input value="${co.regra.humano_min}" style="width:80px;height:36px;padding:0 12px"> min</dd><dt class="muted">Follow-up nos dias</dt><dd style="margin:0" class="mono">${co.regra.toques.join(', ')}</dd></dl></div></div>`;
    if(t==='api')body=`<div class="sec"><div class="h"><h2>Chave e API</h2></div><div class="b" style="padding:18px 20px"><pre style="font-family:var(--mono);font-size:12px;background:var(--surface-2);border-radius:8px;padding:14px 16px;white-space:pre-wrap;margin:0;color:var(--ink-2)">chave        kmp_${co.id}_••••••••••••
whatsapp     Meta Cloud API · 1 número
entrada      POST /v1/leads      formulário, anúncio, indicação
             POST /v1/whatsapp   mensagens da Meta
motores      ${co.motores.map(m=>m.nome).join(' · ')}
saída        webhook por evento: lead_criado, ia_respondeu, chamou_gente, fase_mudou, fechado, perdido
retenção     mensagens 12 meses · CPF, documento e cartão nunca entram</pre></div></div>`;
    return head(`Conector ${co.nome.split(' ·')[0]}`,`<span class="tag g">ativo</span><span class="muted">kmp_${co.id}</span><button class="btn" onclick="K2.exportar()">Exportar JSON</button><button class="btn">Importar</button>`)+`<div class="tabs-h">${tabs.map(x=>`<a href="?t=${x[0]}" class="${t===x[0]?'on':''}">${x[1]}</a>`).join('')}</div>${body}`+fonte();
  };

  /* ---------- ações ---------- */
  window.K2={
    aprovar(id){const l=co.leads.find(x=>x.id===id); if(!l||!l.pend)return; const txt=l.pend.sugestao.replace(/^.*?Rascunho pronto: /,'').replace(/^.*?Sugestão: /,''); const prop=l.pend.tipo.startsWith('Proposta'); l.msgs.push({de:'hum',por:me.id,t:Date.now(),x:prop?'Segue a proposta (PDF). Qualquer dúvida é só falar por aqui.':txt}); l.msgs.push({de:'sys',t:Date.now(),x:`${me.nome} aprovou em ${fmt(Date.now()-l.pend.desde)} · IA retomou`}); l.estado=prop?'proposta':'ia'; if(prop)l.fase='Proposta'; l.pend=null; save(); toast(`<b>Feito.</b> A IA retomou ${l.nome}.`); setTimeout(()=>location.reload(),800)},
    decidir(id){const l=co.leads.find(x=>x.id===id); if(!l||!l.pend)return; l.msgs.push({de:'sys',t:Date.now(),x:`${me.nome} decidiu em ${fmt(Date.now()-l.pend.desde)} · IA retomou`}); l.estado='ia'; l.pend=null; save(); toast(`<b>Decidido.</b> A IA responde ${l.nome}.`); setTimeout(()=>location.reload(),800)},
    devolver(id){const l=co.leads.find(x=>x.id===id); if(!l)return; l.msgs.push({de:'sys',t:Date.now(),x:`${me.nome} devolveu pra IA`}); l.estado='ia'; l.pend=null; save(); toast(`<b>Devolvido.</b>`); setTimeout(()=>location.reload(),800)},
    enviar(id){const l=co.leads.find(x=>x.id===id); const i=document.getElementById('k-in'); if(!l||!i||!i.value.trim())return; const was=l.pend; l.msgs.push({de:'hum',por:me.id,t:Date.now(),x:i.value.trim()}); if(was){l.msgs.push({de:'sys',t:Date.now(),x:`${me.nome} respondeu em ${fmt(Date.now()-was.desde)} · IA retomou`}); l.pend=null; l.estado='ia'} else {l.msgs.push({de:'sys',t:Date.now(),x:`${me.nome} assumiu a conversa`}); l.estado='humano'; l.pend={tipo:'Assumida',regra:'pessoa assumiu por vontade própria',para:me.id,desde:Date.now(),sla_min:co.regra.humano_min,sugestao:'Quando terminar, devolva pra IA seguir o follow-up.'}} save(); location.reload()},
    usarRascunho(el){const i=document.getElementById('k-in'); if(i){i.value=el.textContent; i.focus()}},
    marcar(id,estado){const l=co.leads.find(x=>x.id===id); if(!l)return; l.estado=estado; l.pend=null; if(estado==='fechado')l.fase='Fechado'; if(estado==='perdido')l.fase='Perdido'; l.msgs.push({de:'sys',t:Date.now(),x:`${me.nome} marcou: ${ESTADO[estado]}`}); save(); toast(`<b>${ESTADO[estado]}.</b>`); setTimeout(()=>location.reload(),800)},
    fase(id,f){const l=co.leads.find(x=>x.id===id); if(!l)return; l.fase=f; l.fase_por=me.nome; l.fase_t=Date.now(); l.msgs.push({de:'sys',t:Date.now(),x:`${me.nome} corrigiu a fase pra ${f} · vira regra no playbook`}); save(); toast(`<b>${f}.</b> Corrigido; a IA aprende.`); setTimeout(()=>location.reload(),800)},
    exportar(){exportar()},
    testar(n){const mo=co.motores.find(x=>x.nome===n); toast(`<b>${n}</b> respondeu em ${Math.round(80+Math.random()*300)} ms: ${Object.values(mo.teste.out).slice(0,2).join(' · ')}`)}
  };

  window.K2_page=(name,title)=>{shell({active:name,title:title}); document.querySelector('.k-main').innerHTML=PAGES[name](); const b=document.querySelector('.chat .body'); if(b)b.scrollTop=b.scrollHeight;};
})();
